BEGIN;

SET LOCAL standard_conforming_strings = on;

INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷103·隐帝本纪·郭威起兵与滑州", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/2acb872f407f87ecc1c683ebe4afe35ab5af384e/content/books/zizhi-tongjian/vol-289/year-0950/part-08/sources/library/jiuwudaishi-103-guo-march/source.txt", "note": "《旧五代史》卷103·隐帝本纪·郭威起兵与滑州，段落 jiu-wudaishi-205deb4a7860-p002495；已核上下文及传主，纸本及异文待核。", "id": "15b96e79-6c69-5263-9f78-f78df3564931"}, {"title": "宋史·卷461·赵修己传·离开李守贞至翰林天文", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/2acb872f407f87ecc1c683ebe4afe35ab5af384e/content/books/zizhi-tongjian/vol-289/year-0950/part-08/sources/library/songshi-461-zhao-xiuji-career/source.txt", "note": "《宋史》卷461·赵修己传·离开李守贞至翰林天文，段落 songshi-9c6e46fee832-p073611；已核上下文及传主，纸本及异文待核。", "id": "5df2680b-dad6-51f9-a444-5680230633bb"}, {"title": "资治通鉴·卷289·乾祐三年·南下与禁军赏赐", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/2acb872f407f87ecc1c683ebe4afe35ab5af384e/content/books/zizhi-tongjian/vol-289/year-0950/part-08/sources/library/tongjian-289-950-guo-march/source.txt", "note": "《资治通鉴》卷289·乾祐三年·南下与禁军赏赐，段落 zizhi-tongjian-a63549944a71-p003433；已核上下文及传主，纸本及异文待核。", "id": "06419fad-ee77-5078-bbd8-5e576df0ff8e"}, {"title": "新五代史·卷11·周本纪·郭威南下", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/2acb872f407f87ecc1c683ebe4afe35ab5af384e/content/books/zizhi-tongjian/vol-289/year-0950/part-08/sources/library/xinwudaishi-011-guo-march/source.txt", "note": "《新五代史》卷11·周本纪·郭威南下，段落 xin-wudaishi-b08f244b9241-p000366；已核上下文及传主，纸本及异文待核。", "id": "28c8d935-0552-5d17-ac23-4f322402147c"}, {"title": "资治通鉴·卷289·乾祐三年·丙子诛杀与密诏", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/16c0f5a86200a69c1b027a44e1cd6ceca86246f5/content/books/zizhi-tongjian/vol-289/year-0950/part-07/sources/library/tongjian-289-950-assassination-orders/source.txt", "note": "《资治通鉴》卷289·乾祐三年·丙子诛杀与密诏，段落 zizhi-tongjian-a63549944a71-p003432；已核上下文及传主，纸本及异文待核。", "id": "1435cca5-da95-5076-888b-66438fc4f97c"}, {"title": "新五代史·卷10·汉本纪·乾祐三年十一月", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/16c0f5a86200a69c1b027a44e1cd6ceca86246f5/content/books/zizhi-tongjian/vol-289/year-0950/part-07/sources/library/xinwudaishi-010-han-court-killings/source.txt", "note": "《新五代史》卷10·汉本纪·乾祐三年十一月，段落 xin-wudaishi-b08f244b9241-p000353；已核上下文及传主，纸本及异文待核。", "id": "6d0ba205-beb0-5b8b-a95a-2d1e8dbe90d2"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "李洪义", "aliases": ["李洪義"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉李太后的弟弟，950年任镇宁节度使。刘承祐下密诏令他杀驻澶州的王殷，本段只记命令，未记他已经执行。生卒年未载。", "biography": null, "status": "draft", "id": "12dc9c88-13ce-589c-94c7-384ae0bd7223"}, {"name": "孟业", "aliases": ["孟業"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉供奉官。950年奉刘承祐命携带密诏前往澶州和邺都，传达杀王殷、郭威及王峻等人的命令。生卒年未载。", "biography": null, "status": "draft", "id": "cd735167-b0f8-5ed8-a58c-17e706c26246"}, {"name": "王殷（后汉后周将）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "瀛州籍将领。950年以侍卫步军都指挥使身份奉命驻澶州防备契丹，后来参与后周建国。《旧五代史》记他自称出生在魏州开元寺，籍贯与出生地分开。与晚唐后梁同名王殷分开建档，生卒年本批未录。", "biography": null, "status": "draft", "id": "4b85115a-7337-546f-af4c-9f6bd20f13c6"}, {"name": "陈光穗", "aliases": ["陳光穗"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "950年任澶州副使，奉王殷命将杀害将帅的密诏带给郭威。《旧五代史》说王殷与李洪义共同派遣。生卒年未载，不因同名自动并入早期河东使者。", "biography": null, "status": "draft", "id": "e91f97a0-55e0-5d65-9ac1-273bf67074fe"}, {"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "魏仁浦", "aliases": ["魏仁溥"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "字道济，卫州汲人。后晋末任枢密院小吏，随众被迁往契丹后逃归。947年在巩县迎见刘知远，因熟知军队人数与旧制受到郭威信任。生卒年尚未录入。", "biography": null, "status": "draft", "id": "c2e87754-6e6a-56db-b3e1-45835b2bff92"}, {"name": "郭崇威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "应州马军都指挥使，金城人。937年条中记载他不愿臣服契丹，独自南归。", "biography": null, "status": "draft", "id": "2f1d1823-9873-5df8-83ed-7330578213e6"}, {"name": "曹威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "真定人，950年任邺都行营步军都指挥使。刘承祐密令他与郭崇威杀郭威及监军王峻，本段尚未记实际执行。生卒年未载。", "biography": null, "status": "draft", "id": "c26ccc4f-2658-5be8-b917-885c6c56f287"}, {"name": "赵修己", "aliases": ["趙修己"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "浚仪人，擅长术数。李守贞镇滑州时任司户参军，随后随李守贞移镇。948年叛乱前多次劝其不要轻动，未获采纳，称病回乡。生卒年未载，未将后周同名司天官的经历无证并入。", "biography": null, "status": "draft", "id": "466921a0-4aca-54da-a351-22bfaf8a12b0"}, {"name": "柴荣", "aliases": ["郭荣", "柴榮", "郭榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本姓柴，950年《资治通鉴》以郭荣记名，任贵州刺史、天雄牙内都指挥使。父亲柴守礼是郭威妻子柴氏的兄长，郭威在尚无儿子时收养他。《新五代史》记他幼年跟随姑母在郭威家成长。《旧五代史》的任职纪年与通鉴不同，分别保留。", "biography": null, "status": "draft", "id": "697c1a4f-b373-5a78-8b47-330fe349a424"}, {"name": "慕容彦超", "aliases": ["慕容彥超"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋濮州刺史，原属吐谷浑，与刘知远同母。945年正月随皇甫遇侦察契丹军，在榆林店受围，与皇甫遇共同救回杜知敏，得到安审琦援军后返回相州。出生及死亡年本段未载。", "biography": null, "status": "draft", "id": "e0c11a24-a441-5d69-b8e3-b5bdc109357b"}, {"name": "刘承祐", "aliases": ["劉承祐", "后汉隐帝"], "era": "五代十国", "birth_year": 931, "death_year": null, "description": "刘知远第二子，母亲为李氏。《旧五代史》记他生于931年三月七日的邺都旧宅，曾任左卫大将军和大内都点检。948年二月先封周王，随后依据公布的遗制继承后汉皇位。《资治通鉴》记其即位时十八岁。", "biography": null, "status": "draft", "id": "96b54cac-772d-54e8-b2de-975b3be49e85"}, {"name": "吴虔裕", "aliases": ["吳虔裕"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉河中行营都监。949年四月奉郭威之命，率兵从侧面攻击李守贞出城部队，击败对方并夺取攻城器具。生卒年尚未确定。", "biography": null, "status": "draft", "id": "e576a210-c5b6-5c62-8309-4f25ed7f2693"}, {"name": "侯益", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：侯益，平遥前直指挥使、脱身返洛者。", "biography": null, "status": "draft", "id": "d164db58-b751-53af-9dac-d5112662da44"}, {"name": "阎晋卿", "aliases": ["閻晉卿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "忻州人，后汉客省使。949年正月河中军夜袭后汉营寨时，提醒将士可以凭黄纸甲在火光下辨认敌军。生卒年尚未录入。", "biography": null, "status": "draft", "id": "cd541c62-d1b8-5017-afb5-ae81ba6585ac"}, {"name": "张彦超", "aliases": ["張彥超"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：张彦超，蔚州刺史、举城归契丹者。", "biography": null, "status": "draft", "id": "abfe6397-741d-5795-88f6-462c9ce4b3b1"}, {"name": "鸗脱", "aliases": ["鸗脫", "驡脫"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉内养。950年奉刘承祐命侦察郭威，被郭威抓获后携奏表返回大梁。《新五代史》写驡脫，按相同职务与行动对应，原字保留。生卒年未载。", "biography": null, "status": "draft", "id": "e2e06064-c276-508f-9e7a-763ab4eed024"}, {"name": "宋延渥", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "洛阳人，950年任义成节度使，郭威南下时在滑州迎降。他的妻子是后晋石敬瑭的女儿永宁公主。迎降纪日两部史书有差异，生卒年未载。", "biography": null, "status": "draft", "id": "24f24435-a8b6-5d3e-9f40-ad0e7f494c03"}, {"name": "永宁公主（石敬瑭女）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋石敬瑭的女儿，宋延渥的妻子。与石敬瑭妻子曾获永宁公主封号的李氏分开建档。具体姓名、生卒年与婚期未载。", "biography": null, "status": "draft", "id": "dc142eb9-714a-5c6e-a20a-61e30775a632"}, {"name": "石敬瑭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：石敬瑭。", "biography": null, "status": "draft", "id": "bf42d98c-7477-5be1-a767-867fe26cf617"}, {"name": "王峻", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "安阳人，刘知远的客将。947年奉三表赴契丹，报告贺入大梁、暂不离太原及贡路受阻。《旧五代史》称牙将王峻，记二月出使和携杖回太原。生卒年本段未核。", "biography": null, "status": "draft", "id": "196d9879-50e7-5ff5-9d99-4879fa1ea3a2"}, {"name": "窦贞固", "aliases": ["竇貞固"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：窦贞固，原节度推官、获任者。", "biography": null, "status": "draft", "id": "628caf07-3ba2-5bc4-8630-598667f5bdd0"}, {"name": "李业", "aliases": ["李業"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉李太后的弟弟，任武德使，刘知远时掌内库，刘承祐即位后受到宠信。950年与刘承祐等策划诛杀杨邠等大臣。出生与死亡年本批未录。", "biography": null, "status": "draft", "id": "0a670b8c-fe4d-5003-96e0-ac1c6b99b1a0"}, {"name": "苏禹珪", "aliases": ["蘇禹珪"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "密州人，任河东观察判官。947年刘知远任命他为中书侍郎、同平章事。具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "b8c912f3-4f5e-5fbc-9714-9caaf03ed98c"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "李洪义不敢执行密诏，将孟业引见王殷", "start_year": 950, "end_year": 950, "time_original": "950年十一月丁丑", "dynasty": "五代十国", "description": "李洪义不敢执行密诏，将孟业引见王殷。", "phases": [], "location_name": "澶州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "3a8c50ed-92b9-5886-a3be-b4a9a191b808"}, {"title": "王殷囚禁孟业，派陈光穗把密诏送给郭威", "start_year": 950, "end_year": 950, "time_original": "950年十一月丁丑条下，具体送达时刻未载", "dynasty": "五代十国", "description": "王殷囚禁孟业，派陈光穗把密诏送给郭威。", "phases": [], "location_name": "澶州至邺都", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "790afc4e-4b6d-599f-8871-a215a403176c"}, {"title": "魏仁浦劝郭威不能坐待被杀", "start_year": 950, "end_year": 950, "time_original": "950年十一月丁丑条下，郭威得密诏之后", "dynasty": "五代十国", "description": "魏仁浦劝郭威不能坐待被杀。", "phases": [], "location_name": "邺都", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "02594e40-8224-5fb0-b1c0-ca151154401e"}, {"title": "郭威向郭崇威、曹威等说明密诏，提出让他们杀自己交差", "start_year": 950, "end_year": 950, "time_original": "950年十一月丁丑条下，具体召见时刻未载", "dynasty": "五代十国", "description": "郭威向郭崇威、曹威等说明密诏，提出让他们杀自己交差。", "phases": [], "location_name": "邺都", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "5158da43-f11e-54be-bbc0-35d803f072ce"}, {"title": "郭崇威等拒绝杀郭威，表示愿随他入朝自诉", "start_year": 950, "end_year": 950, "time_original": "950年十一